const raw = $input.first().json;
const body = raw.body ?? raw;

const metrics = {
  production_type:  body.production_type  ?? null,
  total_animals:    body.total_animals    ?? null,
  active_alerts:    body.active_alerts    ?? 0,
  sync_count:       body.sync_count       ?? 0,
  last_sync:        body.last_sync        ?? null,
  critical_records: body.critical_records ?? 0
};

const has_data = !!(metrics.production_type && metrics.total_animals !== null);

return [{ json: { ...metrics, has_data } }];

const m = $input.first().json;
const model = $env.DEEPSEEK_MODEL || 'deepseek-chat';

const systemPrompt = 'You are AURA, FincApp's farm operations assistant. Generate short, safe, and actionable recommendations from farm metrics. You are NOT a veterinarian and must never replace professional veterinary advice. Always include a safety disclaimer when health risks are detected. Respond ONLY with valid JSON in English.';

const userPrompt = 'Farm metrics summary:
- Production type: ' + m.production_type + '
- Total animals: ' + m.total_animals + '
- Active health alerts: ' + m.active_alerts + '
- Recent sync sessions: ' + m.sync_count + '
- Last sync: ' + (m.last_sync || 'never') + '
- High/critical health records in last 7 days: ' + m.critical_records + '

Generate a farm recommendation. Return JSON with: recommendation (one actionable sentence), priority (low/medium/high), category (health/inventory/operations/sync), safe_wording (include if health risk exists, else null), requires_vet (bool).';

return [{ json: { ...m, llm_model: model, prompt_system: systemPrompt, prompt_user: userPrompt } }];

const response = $input.first().json;

const fallback = {
  recommendation: 'Keep monitoring your animals daily and ensure all health events are logged. Regular records help AURA detect patterns early.',
  priority: 'medium',
  category: 'operations',
  safe_wording: 'If you observe any unusual symptoms, consult a licensed veterinarian promptly.',
  requires_vet: false,
  source: 'api_fallback'
};

if (!response.choices || response.choices.length === 0) {
  return [{ json: fallback }];
}

let parsed;
try {
  parsed = JSON.parse(response.choices[0].message.content);
} catch (e) {
  return [{ json: fallback }];
}

const validPriorities = ['low', 'medium', 'high'];
if (!parsed.recommendation || !validPriorities.includes(parsed.priority)) {
  return [{ json: fallback }];
}

return [{ json: { ...parsed, source: 'llm' } }];
